/// - `HostNetworkSystem::network_info.vswitch?[*].spec.policy?.offload_policy?`
/// - `HostProfileManager::apply_host_config_task(config_spec).network?.vswitch?[*].spec?.policy?.offload_policy?`
/// 
/// *(10 of 26 paths)*
pub struct HostNetOffloadCapabilities {
    // Parent field
    pub data_object_: super::structs::DataObject,
    // Fields of HostNetOffloadCapabilities
    /// (Optional) The flag to indicate whether or not checksum
    /// offloading is supported.
    pub csum_offload: Option<bool>,
    /// (Optional) The flag to indicate whether or not TCP segmentation
    /// offloading (TSO) is supported.
    pub tcp_segmentation: Option<bool>,
    /// (Optional) The flag to indicate whether or not zero copy
    /// transmits are supported.
    pub zero_copy_xmit: Option<bool>,
}
